function icon(name, cls) {
    const path = ICON_PATHS[name];
    if (!path) return '';
    return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="${cls || 'w-3.5 h-3.5'} inline-block align-[-3px] shrink-0">${path}</svg>`;
}

// --- UTILS ---
const formatMoney = (num) => {
    // FIX #34 : gestion des montants négatifs (affichait "-2500000 €" brut) et des décimales
    num = Math.round(num || 0);
    const sign = num < 0 ? '-' : '';
    const abs = Math.abs(num);
    if (abs >= 1000000) return sign + (abs / 1000000).toFixed(1) + ' M€';
    if (abs >= 1000) return sign + (abs / 1000).toFixed(0) + ' K€';
    return sign + abs + ' €';
};

