// ═══════════════════════════════════════════════════════════════════════════
// NIVEAUX DE STAFF — on ne recrute plus « un kiné », on choisit SON kiné.
// Cinq paliers : plus le niveau est haut, plus l'effet est fort, plus ça coûte
// (à l'achat comme en salaire). Le multiplicateur d'effet est volontairement
// sous-linéaire par rapport au coût : monter au niveau 5 est un vrai
// arbitrage budgétaire, pas un achat automatique dès qu'on a les moyens.
// ═══════════════════════════════════════════════════════════════════════════
const STAFF_TIERS = [
    { level: 1, label: 'Débutant',    effectMult: 0.45, costMult: 0.35, salaryMult: 0.40 },
    { level: 2, label: 'Confirmé',    effectMult: 0.75, costMult: 0.65, salaryMult: 0.70 },
    { level: 3, label: 'Expérimenté', effectMult: 1.00, costMult: 1.00, salaryMult: 1.00 },
    { level: 4, label: 'Réputé',      effectMult: 1.30, costMult: 1.70, salaryMult: 1.60 },
    { level: 5, label: 'Élite',       effectMult: 1.60, costMult: 2.80, salaryMult: 2.50 }
];

// Un candidat par (rôle, niveau) : nom et visage stables pour la partie, tirés
// du même générateur que les joueurs — le staff a donc une vraie identité.
const _STAFF_CAND_CACHE = new Map();
function staffCandidate(typeId, level, regionId = 'francophone') {
    const key = typeId + level;
    if (_STAFF_CAND_CACHE.has(key)) return _STAFF_CAND_CACHE.get(key);
    const seed = crestSeed(key);
    const rnd = crestRng(seed);
    const pool = REGIONAL_NAMES[regionId] || REGIONAL_NAMES.francophone;
    const name = pool.first[Math.floor(rnd() * pool.first.length)] + ' ' + pool.last[Math.floor(rnd() * pool.last.length)];
    const suits = Object.keys(MANAGER_SUITS);
    const cand = {
        name,
        age: 34 + Math.floor(rnd() * 28),
        suit: suits[Math.floor(rnd() * suits.length)],
        variant: seed % 100000
    };
    _STAFF_CAND_CACHE.set(key, cand);
    return cand;
}

function staffCost(type, level)   { return Math.round(type.cost   * STAFF_TIERS[level - 1].costMult   / 5000) * 5000; }
function staffSalary(type, level) { return Math.round(type.salary * STAFF_TIERS[level - 1].salaryMult / 500) * 500; }
function staffEffect(type, level) { return Math.round(type.base   * STAFF_TIERS[level - 1].effectMult); }

