    defensive: { label: 'Défensif',       mentality: 'defensive', style: 'direct',     atkMod: 0.93, defMod: 1.07, formations: ['5-3-2', '5-4-1', '4-1-4-1'] },
    balanced:  { label: 'Équilibré',      mentality: 'balanced',  style: 'possession', atkMod: 1.00, defMod: 1.00, formations: ['4-4-2', '4-2-3-1', '3-1-4-2'] },
    counter:   { label: 'Contre-attaque', mentality: 'defensive', style: 'counter',    atkMod: 0.97, defMod: 1.04, formations: ['5-2-3', '4-1-4-1', '4-5-1'] },
