// Choisit la bonne banque de réponses selon la nature de l'interview.
function interviewRepliesFor(kind) {
    return (kind === 'playtime' || kind === 'transfer') ? TENSION_INTERVIEW_REPLIES : PRESS_INTERVIEW_REPLIES;
}

